#include "jerico/materials.hpp"
#include <fstream>
#include <iostream>
#include <algorithm>
#include <array>
#include <cmath>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("Expected oblique-pin fixture path");std::ifstream f(argv[1]);jerico::Json scene;f>>scene;jerico::Json before;for(auto&p:scene["parts"])before[p["id"].get<std::string>()]=p["uvs"];auto report=jerico::bake_material_textures(scene,"/tmp/jerico_material_oblique_regression",512);size_t empty=0;for(auto&p:report["parts"]){empty+=p["empty_islands"].get<size_t>();std::cout<<p["id"]<<": "<<p["empty_islands"]<<" empty islands of "<<p["uv_islands"]<<"\n";}if(empty)throw std::runtime_error("Oblique hinge charts contain unbaked faces");for(auto&p:scene["parts"]){if(p["uvs"]!=before[p["id"].get<std::string>()])throw std::runtime_error("Metric UVs changed during chart packing");std::vector<std::array<float,4>> bounds;for(auto&face:p["texture_uvs"]){double area64=0,area32=0;std::array<float,4> box={1,1,0,0};for(size_t i=0;i<face.size();i++){auto a=face[i].get<jerico::V2>(),b=face[(i+1)%face.size()].get<jerico::V2>();float ax=a[0],ay=a[1],bx=b[0],by=b[1];if(ax==bx&&ay==by)throw std::runtime_error("Texture UV edge collapsed after float32/GLB conversion");area64+=a[0]*b[1]-b[0]*a[1];area32+=double(ax)*by-double(bx)*ay;box[0]=std::min(box[0],ax);box[1]=std::min(box[1],ay);box[2]=std::max(box[2],ax);box[3]=std::max(box[3],ay);}if(area64*area32<=0||std::abs(area32)<std::abs(area64)*.9)throw std::runtime_error("Texture face collapsed after float32/GLB conversion");bounds.push_back(box);}for(size_t i=0;i<bounds.size();i++)for(size_t j=i+1;j<bounds.size();j++){auto a=bounds[i],b=bounds[j];if(std::min(a[2],b[2])>std::max(a[0],b[0])&&std::min(a[3],b[3])>std::max(a[1],b[1]))throw std::runtime_error("Texture charts overlap after float32 conversion");}}std::cout<<"Material chart packing regression passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
